import type { EnrichmentGroup, SportEnrichment } from "../enrichment";
import type { DrillSeed, MetricSeed, SourceSeed } from "../types";

/*
 * Combat sports & martial arts learning content.
 * Model: boxing.ts — solo technique (contact level 1), equipment contact (level 2),
 * coach-supervised controlled partner drills (level 3). Sparring is never generated.
 * Grappling arts start with breakfalls, posture and solo movement; throws, takedowns,
 * chokes and joint locks appear only as coach-led partner drills.
 */

const ED = ["apex-editorial"];

const COACH_SCALE = ["1 – learning", "2 – developing", "3 – consistent", "4 – advanced", "5 – competition ready"];

const coach = (key: string, label: string, description?: string): MetricSeed => ({
  key,
  label,
  kind: "select",
  scope: "performance",
  direction: "higher",
  options: COACH_SCALE,
  description,
  measurement: "Recorded by your coach or instructor after observing you in class.",
});

const edition = (body: string) =>
  `General overview written without access to the current rulebook — it has not been checked against it. Rules differ between organisations, age groups and levels and change over time; check the current official rules of ${body} before you compete.`;

const supervision = (art: string, partner: string) =>
  `Solo ${art} technique, movement and conditioning are provided here. All partner and contact work — ${partner} — must be learned and practised under a qualified instructor in a registered club, and partner drills in this app are always marked as supervised. Sparring is never generated.`;

/* Shared safety lines */
const S_HEAD = "Any blow to the head followed by headache, dizziness, confusion, nausea or blurred vision means stop immediately and get medically assessed — no return to training the same day.";
const S_MOUTH = "Mouthguard for every partner drill with any contact, plus the protective equipment your club requires.";
const S_PARTNER = "Every partner drill here requires a qualified instructor present. Agree the drill, the speed and the contact level with your partner before you start.";
const S_TAP =
  "Tap-out rule: to stop, tap your partner or the mat clearly at least twice, or say “tap”. The partner releases instantly and completely. Apply locks and chokes slowly so your partner always has time to tap, and never resist through a lock.";
const S_BREAKFALL = "Breakfalls come before any throw or takedown, and throws are only practised onto proper mats with a coach present.";
const S_PAIN = "Stop for sharp pain, numbness or joint pain — discomfort from effort is normal, joint pain is not.";

