const breakfallDrill = (slug = "breakfall-progression", term = "ukemi"): DrillSeed => ({
  slug,
  title: `Breakfall (${term}) progression`,
  purpose: "Learn to fall backwards and sideways safely — the first skill before any throw or takedown.",
  level: "beginner",
  focus: "technique",
  durationMin: 12,
  setting: "solo",
  contact: "none",
  equipment: ["Proper mats (tatami or thick gym mat) — never on a hard floor"],
  content: {
    setup: ["Clear mat with space all around you.", "If you have a neck or back condition, check with a health professional and your instructor first."],
    instructions: [
      "Back breakfall lying: on your back, chin tucked, arms crossed on the chest. Lift the head, rock a little and slap both arms on the mat at about 45° from the body, palms down. 10 reps.",
      "Back breakfall from sitting: legs out, arms forward, chin tucked. Roll back along a rounded spine and slap at 45° as the upper back lands. 10 reps.",
      "Side breakfall lying: from your back, swing one leg and the same-side arm across the body, roll to that side and slap with the whole arm. 8 each side.",
      "Side breakfall from a squat (only when the lying versions are smooth): slide one leg across in front, sit down close to the support heel and roll to the side, slapping. 6 each side.",
    ],
    coachingPoints: ["Chin tucked throughout — the back of the head never touches the mat.", "Slap with forearm and palm together, arm about 45° from the body; never post a straight arm to catch yourself.", "Exhale sharply as you land.", "Round the back like a rocking chair."],
    progressions: ["Standing and forward rolling breakfalls are learned in class with an instructor before any solo practice."],
    regressions: ["Stay at the lying level until the chin tuck and slap are automatic."],
  },
});

