const STRIKE_WEEKLY = [
  { sessionsPerWeek: 2, pattern: ["technique", "conditioning"] },
  { sessionsPerWeek: 3, pattern: ["technique", "conditioning", "technique"] },
  { sessionsPerWeek: 4, pattern: ["technique", "conditioning", "technique", "recovery"] },
] as const;
const GRAPPLE_WEEKLY = [
  { sessionsPerWeek: 2, pattern: ["technique", "technique"] },
  { sessionsPerWeek: 3, pattern: ["technique", "conditioning", "technique"] },
  { sessionsPerWeek: 4, pattern: ["technique", "conditioning", "technique", "recovery"] },
] as const;
const weekly = (w: typeof STRIKE_WEEKLY | typeof GRAPPLE_WEEKLY) => w.map((x) => ({ sessionsPerWeek: x.sessionsPerWeek, pattern: [...x.pattern] }));

